head.b:skin:
/* إعدادات وتصفير أساسي متوافق مع بلوجر وإخفاء عناصر بلوجر الافتراضية */
html, body {
  margin: 0;
  padding: 0;
  border: 0;
  width: 100%;
  min-height: 100%;
}
.blogger-hidden-area, #b-navbar, .widget-item-control, .quickedit, #navbar-iframe, .status-msg-wrap {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  width: 0 !important;
  overflow: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}
